// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Login (define cookie de sessão)
	// (POST /auth/login)
	Login(c *gin.Context)
	// Logout Encerra a sessão
	// (POST /auth/logout)
	Logout(c *gin.Context)
	// GetMe Usuário atual e suas casas
	// (GET /auth/me)
	GetMe(c *gin.Context)
	// UpdateMe Atualiza o próprio nome e/ou o tema de cor (preferência da conta, vale em todos os aparelhos)
	// (PATCH /auth/me)
	UpdateMe(c *gin.Context)
	// ChangePassword Troca a própria senha (confere a atual) e encerra as OUTRAS sessões do usuário
	// (POST /auth/password)
	ChangePassword(c *gin.Context)
	// ResetPassword Redefine a senha com o link gerado por um admin
	// (POST /auth/password-reset)
	ResetPassword(c *gin.Context)
	// Register Cria usuário a partir de um convite ou cria uma nova casa
	// (POST /auth/register)
	Register(c *gin.Context)
	// EndOtherSessions Sai de todos os outros aparelhos (encerra as sessões do usuário, menos a atual)
	// (DELETE /auth/sessions/others)
	EndOtherSessions(c *gin.Context)
	// LookupCnpj Consulta razão social e nome fantasia de um CNPJ na BrasilAPI (cache e prazo curto)
	// (GET /cnpj/{cnpj})
	LookupCnpj(c *gin.Context, cnpj string)
	// GetHealth Verifica se a API e o banco estão respondendo
	// (GET /healthz)
	GetHealth(c *gin.Context)
	// CreateHousehold Cria uma casa (o usuário vira admin) com categorias padrão
	// (POST /households)
	CreateHousehold(c *gin.Context)
	// DeleteHousehold Exclui a casa (admin, exclusão lógica)
	// (DELETE /households/{householdId})
	DeleteHousehold(c *gin.Context, householdId HouseholdId)
	// GetHousehold Detalhes da casa
	// (GET /households/{householdId})
	GetHousehold(c *gin.Context, householdId HouseholdId)
	// UpdateHousehold Renomeia a casa (admin)
	// (PATCH /households/{householdId})
	UpdateHousehold(c *gin.Context, householdId HouseholdId)
	// ExtractBoleto Extrai dados de um boleto (PDF/PNG/JPG, até 5 MB). Nada é salvo; o usuário revisa antes de criar a invoice.
	// (POST /households/{householdId}/boletos/extract)
	ExtractBoleto(c *gin.Context, householdId HouseholdId)
	// ListCategories Categorias da casa
	// (GET /households/{householdId}/categories)
	ListCategories(c *gin.Context, householdId HouseholdId, params ListCategoriesParams)
	// CreateCategory Cria categoria (member+)
	// (POST /households/{householdId}/categories)
	CreateCategory(c *gin.Context, householdId HouseholdId)
	// DeleteCategory Exclui categoria sem uso e sem subcategorias. Em uso ou com subcategorias, responde 409.
	// (DELETE /households/{householdId}/categories/{categoryId})
	DeleteCategory(c *gin.Context, householdId HouseholdId, categoryId openapi_types.UUID)
	// UpdateCategory Edita ou arquiva categoria
	// (PATCH /households/{householdId}/categories/{categoryId})
	UpdateCategory(c *gin.Context, householdId HouseholdId, categoryId openapi_types.UUID)
	// ExtractDocument Lê contas de um arquivo (boleto, conta sem boleto ou lista). Nada é salvo; o usuário revisa antes de criar.
	// (POST /households/{householdId}/documents/extract)
	ExtractDocument(c *gin.Context, householdId HouseholdId)
	// ParseDocumentText Lê contas de um texto escrito ou colado (mesmo resultado do `extractDocument`). Nada é salvo; o usuário revisa antes de criar.
	// (POST /households/{householdId}/documents/parse-text)
	ParseDocumentText(c *gin.Context, householdId HouseholdId)
	// ExportInvoicesCsv Exporta as contas da casa em CSV (planilha). Todos os membros, inclusive leitura, podem exportar.
	// (GET /households/{householdId}/export/invoices.csv)
	ExportInvoicesCsv(c *gin.Context, householdId HouseholdId, params ExportInvoicesCsvParams)
	// PreviewIncomeDates Prévia das datas de uma regra de data (sem gravar nada)
	// (GET /households/{householdId}/income-dates)
	PreviewIncomeDates(c *gin.Context, householdId HouseholdId, params PreviewIncomeDatesParams)
	// ListIncomeSources Receitas que se repetem (o molde de cada repetição)
	// (GET /households/{householdId}/income-sources)
	ListIncomeSources(c *gin.Context, householdId HouseholdId)
	// CreateIncomeSource Cria uma repetição e gera os lançamentos até o horizonte
	// (POST /households/{householdId}/income-sources)
	CreateIncomeSource(c *gin.Context, householdId HouseholdId)
	// UpdateIncomeSource Edita o molde. `applyFrom` reaplica o molde aos meses a receber a partir dali.
	// (PATCH /households/{householdId}/income-sources/{sourceId})
	UpdateIncomeSource(c *gin.Context, householdId HouseholdId, sourceId openapi_types.UUID, params UpdateIncomeSourceParams)
	// ListIncomes Receitas do mês (recebidas e a receber)
	// (GET /households/{householdId}/incomes)
	ListIncomes(c *gin.Context, householdId HouseholdId, params ListIncomesParams)
	// CreateIncome Lança uma receita (avulsa ou que se repete todo mês)
	// (POST /households/{householdId}/incomes)
	CreateIncome(c *gin.Context, householdId HouseholdId)
	// DeleteIncome Exclusão lógica. Se a receita se repete, `scope` define o alcance.
	// (DELETE /households/{householdId}/incomes/{incomeId})
	DeleteIncome(c *gin.Context, householdId HouseholdId, incomeId openapi_types.UUID, params DeleteIncomeParams)
	// UpdateIncome Edita a receita. Se ela se repete, `scope` define o alcance.
	// (PATCH /households/{householdId}/incomes/{incomeId})
	UpdateIncome(c *gin.Context, householdId HouseholdId, incomeId openapi_types.UUID, params UpdateIncomeParams)
	// UnreceiveIncome "Não caiu": a receita deixa de contar como recebida e fica fora do saldo. Se não contava, 409 `not_received`.
	// (DELETE /households/{householdId}/incomes/{incomeId}/receive)
	UnreceiveIncome(c *gin.Context, householdId HouseholdId, incomeId openapi_types.UUID)
	// ReceiveIncome "Caiu": desfaz o "não caiu" (ou marca como recebida antes da data). Se já conta como recebida, 409 `already_received`.
	// (POST /households/{householdId}/incomes/{incomeId}/receive)
	ReceiveIncome(c *gin.Context, householdId HouseholdId, incomeId openapi_types.UUID)
	// RestoreIncome Desfaz a exclusão. `scope=following` desfaz o lote "este e os seguintes".
	// (POST /households/{householdId}/incomes/{incomeId}/restore)
	RestoreIncome(c *gin.Context, householdId HouseholdId, incomeId openapi_types.UUID, params RestoreIncomeParams)
	// CreateInvite Gera convite por link (admin). O token só é devolvido nesta resposta.
	// (POST /households/{householdId}/invites)
	CreateInvite(c *gin.Context, householdId HouseholdId)
	// RevokeInvite Revoga um convite pendente (admin)
	// (DELETE /households/{householdId}/invites/{inviteId})
	RevokeInvite(c *gin.Context, householdId HouseholdId, inviteId openapi_types.UUID)
	// ListInvoices Lista invoices (tela do mês). Pagas continuam na lista.
	// (GET /households/{householdId}/invoices)
	ListInvoices(c *gin.Context, householdId HouseholdId, params ListInvoicesParams)
	// CreateInvoice Cria invoice avulsa (member+)
	// (POST /households/{householdId}/invoices)
	CreateInvoice(c *gin.Context, householdId HouseholdId)
	// CreateInvoiceBatch Cria várias invoices avulsas de uma vez (member+), tudo ou nada
	// (POST /households/{householdId}/invoices/batch)
	CreateInvoiceBatch(c *gin.Context, householdId HouseholdId)
	// DeleteInvoice Exclusão lógica. Em série, `scope` define o alcance.
	// (DELETE /households/{householdId}/invoices/{invoiceId})
	DeleteInvoice(c *gin.Context, householdId HouseholdId, invoiceId InvoiceId, params DeleteInvoiceParams)
	// GetInvoice Detalhe da invoice (inclui boleto, se houver)
	// (GET /households/{householdId}/invoices/{invoiceId})
	GetInvoice(c *gin.Context, householdId HouseholdId, invoiceId InvoiceId)
	// UpdateInvoice Edita invoice. Em série, `scope` define o alcance.
	// (PATCH /households/{householdId}/invoices/{invoiceId})
	UpdateInvoice(c *gin.Context, householdId HouseholdId, invoiceId InvoiceId, params UpdateInvoiceParams)
	// UnpayInvoice Desfaz o pagamento
	// (DELETE /households/{householdId}/invoices/{invoiceId}/pay)
	UnpayInvoice(c *gin.Context, householdId HouseholdId, invoiceId InvoiceId)
	// PayInvoice Marca como paga (afeta só esta invoice). Pode devolver aviso de saldo de benefício insuficiente.
	// (POST /households/{householdId}/invoices/{invoiceId}/pay)
	PayInvoice(c *gin.Context, householdId HouseholdId, invoiceId InvoiceId)
	// RestoreInvoice Desfaz a exclusão. Em série, `scope=following` desfaz o lote "esta e as seguintes".
	// (POST /households/{householdId}/invoices/{invoiceId}/restore)
	RestoreInvoice(c *gin.Context, householdId HouseholdId, invoiceId InvoiceId, params RestoreInvoiceParams)
	// ListMembers Membros ativos
	// (GET /households/{householdId}/members)
	ListMembers(c *gin.Context, householdId HouseholdId)
	// RemoveMember Remove o membro (admin) ou sai da casa (o próprio). Define `left_at`.
	// (DELETE /households/{householdId}/members/{userId})
	RemoveMember(c *gin.Context, householdId HouseholdId, userId UserId)
	// UpdateMemberRole Altera a role (admin). Mantém ao menos um admin ativo.
	// (PATCH /households/{householdId}/members/{userId})
	UpdateMemberRole(c *gin.Context, householdId HouseholdId, userId UserId)
	// CreatePasswordResetLink Gera link de redefinição de senha para um membro (admin de todas as casas dele)
	// (POST /households/{householdId}/members/{userId}/password-reset-link)
	CreatePasswordResetLink(c *gin.Context, householdId HouseholdId, userId UserId)
	// ListPayees Favorecidos da casa
	// (GET /households/{householdId}/payees)
	ListPayees(c *gin.Context, householdId HouseholdId, params ListPayeesParams)
	// CreatePayee Cria favorecido (member+)
	// (POST /households/{householdId}/payees)
	CreatePayee(c *gin.Context, householdId HouseholdId)
	// DeletePayee Exclui favorecido sem uso. Em uso, responde 409 (arquive em vez disso).
	// (DELETE /households/{householdId}/payees/{payeeId})
	DeletePayee(c *gin.Context, householdId HouseholdId, payeeId openapi_types.UUID)
	// UpdatePayee Edita ou arquiva favorecido
	// (PATCH /households/{householdId}/payees/{payeeId})
	UpdatePayee(c *gin.Context, householdId HouseholdId, payeeId openapi_types.UUID)
	// ListPurchases Compras parceladas ("quando comprei o notebook?")
	// (GET /households/{householdId}/purchases)
	ListPurchases(c *gin.Context, householdId HouseholdId, params ListPurchasesParams)
	// CreatePurchase Cria compra parcelada e gera todas as parcelas (passadas e futuras)
	// (POST /households/{householdId}/purchases)
	CreatePurchase(c *gin.Context, householdId HouseholdId)
	// GetPurchase Compra com todas as parcelas
	// (GET /households/{householdId}/purchases/{purchaseId})
	GetPurchase(c *gin.Context, householdId HouseholdId, purchaseId openapi_types.UUID)
	// ListRecurrences Contas recorrentes
	// (GET /households/{householdId}/recurrences)
	ListRecurrences(c *gin.Context, householdId HouseholdId)
	// CreateRecurrence Cria recorrência e gera invoices até o horizonte
	// (POST /households/{householdId}/recurrences)
	CreateRecurrence(c *gin.Context, householdId HouseholdId)
	// UpdateRecurrence Edita ou encerra (end_month) a recorrência
	// (PATCH /households/{householdId}/recurrences/{recurrenceId})
	UpdateRecurrence(c *gin.Context, householdId HouseholdId, recurrenceId openapi_types.UUID)
	// GetMonthlySummary Resumo do mês por competência, com saldos por carteira
	// (GET /households/{householdId}/summary)
	GetMonthlySummary(c *gin.Context, householdId HouseholdId, params GetMonthlySummaryParams)
	// GetCategoryHistory Gasto por categoria mês a mês (histórico para os gráficos), por competência
	// (GET /households/{householdId}/summary/categories)
	GetCategoryHistory(c *gin.Context, householdId HouseholdId, params GetCategoryHistoryParams)
	// EstimateTax Estimativa de INSS e IRRF de um salário mensal (sugestão para preencher descontos)
	// (GET /households/{householdId}/tax/estimate)
	EstimateTax(c *gin.Context, householdId HouseholdId, params EstimateTaxParams)
	// AcceptInvite Usuário logado entra em outra casa com um token de convite
	// (POST /invites/accept)
	AcceptInvite(c *gin.Context)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandler       func(*gin.Context, error, int)
}

type MiddlewareFunc func(c *gin.Context)

// Login operation middleware
func (siw *ServerInterfaceWrapper) Login(c *gin.Context) {

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.Login(c)
}

// Logout operation middleware
func (siw *ServerInterfaceWrapper) Logout(c *gin.Context) {

	for _, middleware := range siw.HandlerMiddlewares {
		middleware(c)
		if c.IsAborted() {
			return
		}
	}

	siw.Handler.Logout(c)
}

